// Render a rule-level hint with a tiny, safe markup vocabulary:
//   `code`   → an inline code chip
//   **bold** → a <strong> emphasis
// HTML is escaped first, so a hint string (from i18n) can never inject markup.
export function renderRuleHint(markup: string): string {
  const escaped = markup
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
  return escaped
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/`([^`]+)`/g, '<code class="rb-code">$1</code>');
}

