// ---- Value coercion -----------------------------------------------------

function coerce(raw: string): unknown {
  const t = raw.trim();
  if (t === '') return '';
  if (t === 'true') return true;
  if (t === 'false') return false;
  const n = Number(t);
  if (!Number.isNaN(n) && /^-?\d*\.?\d+$/.test(t)) return n;
  return t;
}

// ---- Assemble: builder form → API rule ----------------------------------

// Substring / prefix / suffix operators: the value is a text needle, kept as a
// raw string so a value like "007" isn't coerced to the number 7.
const TEXT_MATCH_OPS: ConditionOp[] = ['contains', 'starts_with', 'ends_with'];

function conditionToJson(c: BuilderCondition): CustomRuleCondition {
  let node: CustomRuleCondition;
  if (c.op === 'empty') {
    node = { op: 'empty', field: c.field };
  } else if (c.op === 'not_empty') {
    node = { op: 'not_empty', field: c.field };
  } else if (c.op === 'in') {
    const values = c.value.split(',').map((v) => coerce(v)).filter((v) => v !== '');
    node = { op: 'in', field: c.field, value: values };
  } else if (TEXT_MATCH_OPS.includes(c.op)) {
    node = { op: c.op, field: c.field, value: c.value };
  } else {
    node = { op: c.op, field: c.field, value: coerce(c.value) };
  }
  // Attach the flag only when set AND the op can honor it, so numeric/presence
  // nodes stay clean and round-trip unchanged.
  if (c.case_insensitive && opSupportsCaseInsensitive(c.op)) {
    node.case_insensitive = true;
  }
  return c.negate ? { not: node } : node;
}

// Recursively serialize a group into its all/any node. Leaf conditions
// without a chosen field and empty sub-groups are dropped.
function groupToJson(group: BuilderGroup): CustomRuleAppliesWhen {
  const nodes: CustomRuleCondition[] = [];
  for (const item of group.conditions) {
    if (isBuilderGroup(item)) {
      const child = groupToJson(item);
      const childList = (child[item.join] as CustomRuleCondition[]) || [];
      if (childList.length > 0) nodes.push(child as CustomRuleCondition);
    } else if (item.field) {
      nodes.push(conditionToJson(item));
    }
  }
  return { [group.join]: nodes };
}

// Serialize a builder group into its applies_when node. Exported because the
// transformation-rule builder edits the SAME condition tree and reuses this.
export function buildAppliesWhenFromGroup(group: BuilderGroup): CustomRuleAppliesWhen {
  return groupToJson(group);
}

// True when an applies_when node carries no conditions (e.g. { all: [] } or
// { any: [] }). Such a node is meaningless to the backend, so we omit the key
// entirely rather than send an empty match. Shared by the custom-validation
// builder and the layout-selection-rule drawer.
export function isAppliesWhenEmpty(aw: CustomRuleAppliesWhen): boolean {
  const all = Array.isArray(aw.all) ? aw.all : [];
  const any = Array.isArray(aw.any) ? aw.any : [];
  return all.length === 0 && any.length === 0;
}

// A flat (non-nested) condition, as edited by the layout-selection-rule drawer.
export interface FlatCondition {
  field: string;
  op: ConditionOp;
  value: string;
  negate?: boolean;
}

// Serialize a flat all/any condition list into an applies_when node, reusing the
// same leaf encoding (value coercion, `in` arrays, `not` wrapping) as the nested
// builder. Fieldless leaves are dropped. Centralized so the drawer and the
// custom-validation builder emit identical condition JSON.
export function flatConditionsToAppliesWhen(
  match: 'all' | 'any',
  conditions: FlatCondition[],
): CustomRuleAppliesWhen {
  const group = newGroup(match);
  group.conditions = conditions
    .filter((c) => c.field)
    .map((c) => ({
      kind: 'condition',
      field: c.field,
      op: c.op,
      value: c.value,
      negate: !!c.negate,
      case_insensitive: false,
      isPath: isJsonPath(c.field),
    }) as BuilderCondition);
  return buildAppliesWhenFromGroup(group);
}

function buildAssertion(m: BuilderModel): Record<string, unknown> {
  switch (m.assertion_type) {
    case 'required':
      return { type: 'required' };
    case 'pattern':
      return { type: 'pattern', regex: m.regex };
    case 'arithmetic':
      return {
        type: 'arithmetic',
        expression: m.expression,
        tolerance: m.tolerance === '' ? 0 : Number(m.tolerance),
      };
    case 'range':
      return {
        type: 'range',
        min: m.range_min === '' ? null : Number(m.range_min),
        max: m.range_max === '' ? null : Number(m.range_max),
      };
    case 'field_comparison':
      return {
        type: 'field_comparison',
        op: m.compare_op,
        left: m.compare_left,
        right: { field: m.compare_right },
      };
    case 'allowed_values':
      // Manual fixed list — the original shape, unchanged so old rules round-trip.
      return {
        type: 'allowed_values',
        values: m.allowed_values
          .split('\n')
          .map((v) => coerce(v))
          .filter((v) => v !== ''),
      };
    case 'list_of_values': {
      // Same backend assertion type; values come from a named LOV via `source`.
      const assertion: Record<string, unknown> = {
        type: 'allowed_values',
        source: { from: 'list_of_values', lov_name: m.lov_name },
      };
      if (m.case_insensitive) {
        assertion.case_insensitive = true;
      }
      return assertion;
    }
    default:
      return {};
  }
}

// Mirror the backend's rule_key derivation exactly so the value shown here
// matches what the server computes:
//   slug = re.sub(r"[^a-z0-9]+", "_", str(display_name).lower()).strip("_")
// capped at 100 chars.
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 100);
}

export function assembleApiCore(m: BuilderModel): UpdateValidationRulePayload {
  const core: UpdateValidationRulePayload = {
    display_name: m.display_name,
    description: m.description,
    target_field: m.target_field,
    assertion: buildAssertion(m),
    error_code: m.error_code,
    error_message: m.error_message,
    severity: m.severity,
    priority: Number(m.priority) || 0,
    is_active: m.is_active,
    log_execution: m.log_execution,
  };
  // Send the table for line/whole-table rules so it round-trips (a PUT that
  // omits it could drop the rule's table server-side). Header rules carry none.
  if ((m.scope === 'line' || m.scope === 'table') && m.table_name) {
    core.table_name = m.table_name;
  }
  // Only attach applies_when when the user actually built conditions — an
  // empty group serializes to { all: [] }, which we skip so the param is
  // omitted rather than sent empty.
  const appliesWhen = buildAppliesWhenFromGroup(m.group);
  if (!isAppliesWhenEmpty(appliesWhen)) {
    core.applies_when = appliesWhen;
  }
  return core;
}

// ---- Parse: API rule → builder form (edit mode) -------------------------

// Turn one applies_when node into a builder leaf condition.
function leafFromNode(node: CustomRuleCondition): BuilderCondition {
  let inner = node;
  let negate = false;
  if (node && typeof node === 'object' && 'not' in node && node.not) {
    inner = node.not as CustomRuleCondition;
    negate = true;
  }
  const op = (inner.op as ConditionOp) || 'eq';
  let value = '';
  if (op === 'in' && Array.isArray(inner.value)) value = (inner.value as unknown[]).join(', ');
  else if (inner.value !== undefined && inner.value !== null) value = String(inner.value);
  const field = String(inner.field || '');
  // A field that is a raw JSON path re-opens in path mode on load.
  return {
    kind: 'condition',
    field,
    op,
    value,
    negate,
    case_insensitive: !!inner.case_insensitive,
    isPath: isJsonPath(field),
  };
}

// Recursively parse an applies_when subtree into a builder group. A node
// carrying `all`/`any` becomes a nested group; anything else is a leaf.
// Exported because the transformation-rule builder parses the SAME tree.
export function groupFromAppliesWhen(node: CustomRuleAppliesWhen, join: 'all' | 'any'): BuilderGroup {
  const list = (node[join] as CustomRuleCondition[]) || [];
  const group = newGroup(join);
  group.conditions = list.map((raw) => {
    const asObj = raw as CustomRuleAppliesWhen;
    if (asObj && typeof asObj === 'object' && Array.isArray(asObj.all)) {
      return groupFromAppliesWhen(asObj, 'all');
    }
    if (asObj && typeof asObj === 'object' && Array.isArray(asObj.any)) {
      return groupFromAppliesWhen(asObj, 'any');
    }
    return leafFromNode(raw);
  });
  return group;
}

export function fromApiRule(rule: CustomValidationRule): BuilderModel {
  const m = emptyModel(rule.scope);
  m.rule_key = rule.rule_key || '';
  m.display_name = rule.display_name || '';
  m.description = rule.description || '';
  m.target_field = rule.target_field || '';
  m.table_name = rule.table_name || '';
  m.severity = rule.severity || 'error';
  m.error_code = rule.error_code || '';
  m.error_message = rule.error_message || '';
  m.priority = rule.priority || 0;
  m.is_active = !!rule.is_active;
  m.log_execution = !!rule.log_execution;

  // applies_when: the top-level all/any becomes the root group, parsed
  // recursively so nested sub-groups round-trip.
  const aw = rule.applies_when || {};
  const join: 'all' | 'any' = Array.isArray(aw.any) ? 'any' : 'all';
  m.group = groupFromAppliesWhen(aw, join);

  // assertion
  const a = (rule.assertion || {}) as Record<string, unknown>;
  const at = String(a.type || 'required') as AssertionType;
  m.assertion_type = at;
  if (at === 'pattern') m.regex = String(a.regex || '');
  else if (at === 'arithmetic') {
    m.expression = String(a.expression || '');
    m.tolerance = a.tolerance != null ? String(a.tolerance) : '';
  } else if (at === 'range') {
    m.range_min = a.min != null ? String(a.min) : '';
    m.range_max = a.max != null ? String(a.max) : '';
  } else if (at === 'field_comparison') {
    m.compare_op = (a.op as ConditionOp) || 'gte';
    m.compare_left = String(a.left || '');
    const right = a.right as Record<string, unknown> | undefined;
    m.compare_right = right ? String(right.field ?? right.context ?? '') : '';
  } else if (at === 'allowed_values') {
    // Backend uses one `allowed_values` type; a `source` from a LOV maps to the
    // "List of Values" card, everything else to the manual "Allowed values" card.
    const source = a.source as { from?: string; lov_name?: string } | undefined;
    if (source && source.from === 'list_of_values') {
      m.assertion_type = 'list_of_values';
      m.lov_name = String(source.lov_name || '');
      m.case_insensitive = !!a.case_insensitive;
    } else {
      const vals = (a.values as unknown[]) || [];
      m.allowed_values = vals.join('\n');
    }
  }
  return m;
}

// ---- Plain-English preview ---------------------------------------------

const OP_WORDS: Record<ConditionOp, string> = {
  eq: 'is',
  neq: 'is not',
  in: 'is one of',
  contains: 'contains',
  starts_with: 'starts with',
  ends_with: 'ends with',
  empty: 'is empty',
  not_empty: 'has a value',
  gt: '>',
  lt: '<',
  gte: '≥',
  lte: '≤',
  matches: 'matches',
};

function describeCondition(c: BuilderCondition): string {
  const field = c.field || '(field)';
  const neg = c.negate ? 'not ' : '';
  if (c.op === 'empty') return `${neg}${field} ${OP_WORDS.empty}`;
  if (c.op === 'not_empty') return `${neg}${field} ${OP_WORDS.not_empty}`;
  if (c.op === 'in') return `${neg}${field} ${OP_WORDS.in} [${c.value || '…'}]`;
  return `${neg}${field} ${OP_WORDS[c.op]} ${c.value || '…'}`;
}

function describeAssertion(m: BuilderModel): string {
  const field = m.target_field || '(target)';
  switch (m.assertion_type) {
    case 'required':
      return `${field} must have a value`;
    case 'pattern':
      return `${field} must match ${m.regex || '(pattern)'}`;
    case 'arithmetic':
      return `${m.expression || '(formula)'}${m.tolerance ? ` (within ±${m.tolerance})` : ''}`;
    case 'range':
      return `${field} must be between ${m.range_min || '−∞'} and ${m.range_max || '∞'}`;
    case 'field_comparison':
      return `${m.compare_left || field} ${OP_WORDS[m.compare_op]} ${m.compare_right || '(field)'}`;
    case 'allowed_values':
      return `${field} must be one of: ${m.allowed_values.split('\n').filter(Boolean).join(', ') || '(values)'}`;
    case 'list_of_values':
      return `${field} must be a value from the list "${m.lov_name || '(list)'}"`;
    default:
      return '';
  }
}

function describeGroup(group: BuilderGroup): string {
  const parts = group.conditions
    .map((item) => (isBuilderGroup(item) ? `(${describeGroup(item)})` : describeCondition(item)))
    .filter((p) => p && !p.endsWith('(field)'));
  const joiner = group.join === 'all' ? ' and ' : ' or ';
  return parts.join(joiner);
}

export function describeRule(m: BuilderModel): string {
  const when = describeGroup(m.group);
  const rowScope = m.scope === 'line' ? 'For each table row' : m.scope === 'table' ? 'Across the whole table' : 'When';
  if (!when) {
    return `Always → ${describeAssertion(m)}.`;
  }
  return `${rowScope} ${when} → ${describeAssertion(m)}.`;
}
